PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE semantic_memory (id INTEGER PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, project TEXT CHECK (length (project) <= 128), topic TEXT CHECK (length (topic) <= 128), category TEXT NOT NULL CHECK (category IN ('baseline', 'user', 'feedback', 'project', 'reference', 'pattern')), source TEXT CHECK (length (source) <= 128), model TEXT CHECK (length (model) <= 128), embed_model TEXT CHECK (length (embed_model) <= 128), memory_text TEXT NOT NULL CHECK (length (memory_text) <= 2000), file_reference TEXT, embedding F32_BLOB (1024), superseded_by INTEGER REFERENCES semantic_memory (id), retired_at TEXT);
INSERT INTO "semantic_memory" VALUES(1,'2026-01-01 00:00:00','2026-01-01 00:00:00',NULL,NULL,'reference',NULL,NULL,'bge-m3','line one
line ''two'' "dq" über; end',NULL,X'',NULL,NULL);
INSERT INTO "semantic_memory" VALUES(2,'2026-01-02 00:00:00','2026-01-02 00:00:00',NULL,NULL,'project',NULL,NULL,NULL,'no vector; mentions __turso_internal_seq___turso_internal_autoincrement_odd on purpose',NULL,NULL,NULL,NULL);
INSERT INTO "semantic_memory" VALUES(3,'2026-01-03 00:00:00','2026-01-03 00:00:00',NULL,NULL,'feedback',NULL,NULL,NULL,'-- not a comment; /* nor this */
INSERT INTO "semantic_memory" VALUES(1);
CREATE TRIGGER x AFTER INSERT ON t BEGIN SELECT 1; END;
COMMIT;',NULL,NULL,NULL,NULL);
CREATE TABLE episodic_memory (id INTEGER PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, project TEXT CHECK (length (project) <= 128), topic TEXT CHECK (length (topic) <= 128), event_type TEXT NOT NULL CHECK (event_type IN ('project_start', 'bug_fix', 'feature_complete', 'decision', 'milestone', 'incident', 'note')), importance TEXT NOT NULL CHECK (importance IN ('routine', 'notable', 'major')), source TEXT CHECK (length (source) <= 128), model TEXT CHECK (length (model) <= 128), embed_model TEXT CHECK (length (embed_model) <= 128), memory_text TEXT NOT NULL CHECK (length (memory_text) <= 2000), file_reference TEXT, embedding F32_BLOB (1024), processed_at TEXT);
INSERT INTO "episodic_memory" VALUES(1,'2026-01-04 00:00:00',NULL,NULL,'note','routine',NULL,NULL,NULL,'an event
over two lines
and a tab	here',NULL,NULL,NULL);
INSERT INTO "episodic_memory" VALUES(2,'2026-01-05 00:00:00',NULL,NULL,'decision','notable',NULL,NULL,'bge-m3','an embedded event',NULL,X'',NULL);
CREATE TABLE topic_keywords (topic TEXT NOT NULL PRIMARY KEY, keywords TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO "topic_keywords" VALUES('backup','dump, gzip','2026-01-01 00:00:00');
CREATE TABLE coworkers (id INTEGER PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, name TEXT NOT NULL UNIQUE CHECK (length (name) <= 64), expertise TEXT NOT NULL CHECK (length (expertise) <= 3000), personality TEXT NOT NULL CHECK (length (personality) <= 3000), trust_level TEXT NOT NULL DEFAULT 'supervised' CHECK (trust_level IN ('supervised', 'trusted', 'autonomous')), active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)));
INSERT INTO "coworkers" VALUES(1,'2026-01-01 00:00:00','2026-01-01 00:00:00','reviewer','rust','terse','supervised',1);
CREATE TABLE memory_coworkers (memory_table TEXT NOT NULL CHECK (memory_table IN ('semantic', 'episodic')), memory_id INTEGER NOT NULL, coworker_id INTEGER NOT NULL REFERENCES coworkers (id), PRIMARY KEY (memory_table, memory_id, coworker_id));
INSERT INTO "memory_coworkers" VALUES('semantic',1,1);
CREATE TABLE appraisals (id INTEGER PRIMARY KEY, coworker_id INTEGER NOT NULL REFERENCES coworkers (id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, period_start TEXT, trust_level TEXT NOT NULL CHECK (trust_level IN ('supervised', 'trusted', 'autonomous')), memory_text TEXT NOT NULL CHECK (length (memory_text) <= 2000), superseded_by INTEGER REFERENCES appraisals (id));
CREATE TABLE eval_cases (id TEXT PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, class TEXT NOT NULL CHECK (length (class) <= 32), memory_table TEXT NOT NULL CHECK (memory_table IN ('semantic', 'episodic')), "query" TEXT NOT NULL CHECK (length ("query") BETWEEN 1 AND 512), expect_ids TEXT NOT NULL CHECK (length (expect_ids) <= 256), expect_stamps TEXT NOT NULL CHECK (length (expect_stamps) <= 512), retired_at TEXT);
CREATE TABLE eval_runs (id INTEGER PRIMARY KEY, ran_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, alpha REAL NOT NULL, embed_model TEXT NOT NULL CHECK (length (embed_model) <= 128), n_cases INTEGER NOT NULL, r1 REAL NOT NULL, r5 REAL NOT NULL, mrr REAL NOT NULL);
CREATE TABLE instructions (id INTEGER PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, memory_text TEXT NOT NULL, embed_model TEXT, embedding F32_BLOB (1024), retired_at TEXT);
INSERT INTO "instructions" VALUES(1,'2026-01-06 00:00:00','always
run the tests; then ''lint''',NULL,NULL,NULL);
INSERT INTO "instructions" VALUES(2,'2026-01-07 00:00:00','an embedded instruction','bge-m3',X'',NULL);
CREATE TABLE odd (id INTEGER PRIMARY KEY AUTOINCREMENT, x TEXT);
INSERT INTO "odd" VALUES(1,'a');
INSERT INTO "odd" VALUES(2,'b');
CREATE TABLE "__turso_internal_seq___turso_internal_autoincrement_odd"(value INTEGER PRIMARY KEY,is_called INTEGER,start INTEGER,inc INTEGER,min INTEGER,max INTEGER,cycle INTEGER);
INSERT INTO "__turso_internal_seq___turso_internal_autoincrement_odd" VALUES(1,0,1,1,1,9223372036854775807,0);
DELETE FROM sqlite_sequence;
INSERT INTO sqlite_sequence(name,seq) VALUES('odd',3);
CREATE VIEW current_semantic AS SELECT id, topic FROM semantic_memory WHERE superseded_by IS NULL;
CREATE INDEX IF NOT EXISTS idx_sem_category ON semantic_memory (category);
CREATE INDEX IF NOT EXISTS idx_sem_current ON semantic_memory (superseded_by);
CREATE INDEX IF NOT EXISTS idx_sem_project ON semantic_memory (project);
CREATE INDEX IF NOT EXISTS idx_epi_type ON episodic_memory (event_type);
CREATE INDEX IF NOT EXISTS idx_epi_project ON episodic_memory (project);
CREATE INDEX IF NOT EXISTS idx_epi_processed ON episodic_memory (processed_at);
CREATE INDEX IF NOT EXISTS idx_mc_coworker ON memory_coworkers (coworker_id);
CREATE INDEX IF NOT EXISTS idx_appr_coworker ON appraisals (coworker_id);
CREATE INDEX IF NOT EXISTS idx_appr_current ON appraisals (superseded_by);
CREATE INDEX IF NOT EXISTS idx_eval_case_live ON eval_cases (retired_at);
CREATE INDEX IF NOT EXISTS idx_eval_runs_time ON eval_runs (ran_at);
CREATE INDEX idx_instructions_live ON instructions (retired_at);
CREATE TRIGGER odd_touch AFTER UPDATE ON odd BEGIN SELECT 1; END;
COMMIT;
